  _ = `Kategorie ändern`,
  v = `Kategorie`,
  y = `Sie können die Kategorie für ein Event nicht ändern, für das Sie eine Update-Startseite aktiviert haben. Sie müssen diese zunächst unter dem Tab „Startseite“ deaktivieren, wenn Sie die Kategorie ändern wollen.`,
  b = `Die Kategorie einer Erstellerseite kann nicht geändert werden.`,
  x = `Sie können die Kategorie eines großen Updates, das mit einer Marketingnachricht verbunden ist, nicht ändern.`,
  S = `Spielupdate`,
  C = `Informieren Sie Ihre Spieler über große oder kleine Updates, neue Inhalte, Änderungen der Funktionalität und Fehlerbehebungen.`,
  w = `Laden Sie Fans ein, mit Ihnen zu interagieren, zu reden, die Entwickler kennenzulernen oder Fragen zu stellen`,
  T = `Lassen Sie Spieler wissen, dass Ihr Spiel jetzt verfügbar ist.`,
  E = `Regen Sie Ihre Spieler an, eine Übertragung Ihres Spiels anzuschauen, wie beispielsweise ein Turnier, einen Entwickler-Livestream oder einen berühmten Streamer.`,
  D = `Ideal für kleinere Fehlerbehebungen und Änderungen, die einen Teil Ihrer Spieler betreffen.`,
  O = `Am besten für regelmäßige Funktionsupdates geeignet, die üblicherweise wöchentlich oder monatlich stattfinden.`,
  k = `Diese Ankündigungen eigen sich am besten für Ihre größten Updates, die üblicherweise einmal pro Quartal oder wenige Male im Jahr veröffentlicht werden.`,
  A = `Kündigen Sie käufliche Zusatzinhalte für Ihr Spiel an.`,
  j = `Teilen Sie Spielern den genauen Zeitpunkt Ihrer Veröffentlichung mit.`,
  M = `Kündigen Sie ein zeitlich begrenztes Angebot auf dieses Spiel an.`,
  N = `Künden Sie einen Rabatt auf Gegenstände an, die für bestehende Spieler von Interesse sein könnten, wie virtuelle Gegenstände, virtuelle Währungen oder Zusatzinhalte.`,
  P = `Kündigen Sie einen Zeitraum an, in dem Spieler zusätzliche Punkte für das Spielen Ihres Spiels erhalten.`,
  F = `Kündigen Sie die Chance an, limitierte, neue und seltene oder einzigartige Gegenstände zu finden. Oder erhöhen Sie die Wahrscheinlichkeit, die Gegenstände durch Teilnahme am Spiel zu erhalten.`,
  I = `Kündigen Sie an, dass Spieler vorübergehend Boni oder Prämien im Spiel erhalten, wenn sie Aufgaben abschließen oder an Communityevents teilnehmen.`,
  L = `Eine tägliche, wöchentliche, monatliche oder besondere Herausforderung`,
  R = `Animieren Sie Ihre Fans kreativ zu werden und an Wettbewerben teilzunehmen. Es können Artworks sein, Workshop-Inhalte, Mehrspieler-Wettkämpfe usw.`,
  z = `Laden Sie Ihre Fans ein, mit Ihnen im richtigen Leben Zeit zu verbringen oder erzählen Sie ihnen, wenn Sie etwas Interessantes unternehmen.`,
  B = `Erzählen Sie Spielern etwas Neues. Einen Meilenstein erreicht? Oder vielleicht etwas anderes Interessantes?`,
  V = `Planen oder kündigen Sie Details zur Betateilnahme an.`,
  H = `Ein Angebot für Steam-Kunden, Ihr Spiel, Zusatzinhalte oder Spielinhalte für kurze Zeit kostenlos zu testen. Dies kann ein kostenloses Wochenende, eine Spieldemo oder eine andere Form von kurzzeitigem Zugriff auf Inhalte sein.`,
  U = `Machen Sie auf Ihren neuen Saison- oder Schlachtenpass aufmerksam. Dies ist in der Regel ein Zeitraum von Wochen oder Monaten, in dem Sie zusätzliche Inhalte, Vergünstigungen oder kleinere Events veranstalten.`,
  W = `Verwenden Sie diese Kategorie, wenn Sie über ein anderes demnächst veröffentlichtes Spiel reden möchten oder eine andere Plattform, für die Ihr Spiel bald verfügbar ist. Wählen Sie ausschließlich diese Kategorie für Beiträge zu anderen Spielen, Plattformen oder Shops.`,
  G = `Motivieren Sie Ihre Spieler, Ihr Spiel für eine bestimmte Zeit gemeinsam zu spielen.`,
  K = `Veranstalten Sie ein besonderes Event in Ihrem Spiel mit temporären Halloween-Motiven.`,
  q = `Passen Sie Ihre Erstellerseite an (Entwickler-, Publisher- oder Franchise-Seite). Es wird die zuletzt öffentlich sichtbare Version angezeigt.`,
  J = `Kündigen Sie neue virtuelle Gegenstände oder Spielinhalte an, die jetzt in Ihrem Spiel verfügbar sind.`,
  Y = `Teilen Sie Ihren Steam-Kunden neue Details über Ihren kürzlich veröffentlichten Saison- oder Kampfpass mit. Am besten geeignet, um die Häufigkeit auf einen bestimmten Zeitraum beschränkter Inhaltsupdates festzulegen.`,
  X = `Spiel- oder Inhaltsveröffentlichung/Betatest`,
  Z = `Kündigen Sie den Zeitpunkt der Veröffentlichung Ihres Spiels, Beta, Zusatzinhalts oder Sondersaison an.`,
  Q = `Beschreiben Sie die Veröffentlichung Ihrer Zusatzinhalte oder Ihres Saison- oder Kampfpasses. Teilen Sie Kunden mit, was sie erwarten können und ob die Inhalte käuflich zu erwerben oder kostenlos sind.`,
  ne = `Livestream-Events können auf eine Steam-Übertragung oder eine externe Streamingseite verlinken. Sie können Start- und Endzeiten festlegen. Steam-Übertragungen können auf Ihrer Shopseite und Erstellerseite angezeigt werden.`,
  re = `Wählen Sie die Art Ihres Livestreams`,
  ie = `Rabatt, Promotion oder kostenlose Testversion`,
  ae = `Für Rabatte, Testversionen oder Promotionen für Ihr Spiel, Ihren Zusatzinhalt oder Spielinhalt. Informieren Sie potenzielle Spieler über einen Rabatt auf Ihr Spiel oder bestehende Spieler über einen Rabatt auf Spielinhalte.`,
  oe = `Rabatte werden üblicherweise erst zum Startzeitpunkt sichtbar. Hier können Sie eine Rabattaktion zusammen mit einer Ankündigung und einem Artwork planen.`,
  se = `Wählen Sie die Art des Rabatts aus`,
  ce = `Planen Sie einen Rabatt auf Ihr Spiel oder Zusatzinhalte, der im Steam-Shop erscheinen soll.`,
  le = `Spielevent`,
  ue = `Informieren Sie Spieler über den Zeitraum des Spielevents, damit sie daran teilnehmen und Belohnungen absahnen oder einfach Freunde treffen können.`,
