  fe = `Motivieren Sie Ihre Spieler, Ihr Spiel für bestimmte Belohnungen oder Boni zu spielen.`,
  pe = `Kündigen Sie ein vorübergehendes Event in Ihrem Spiel an. So können Spieler besondere Gegenstände, Boni, Perks, Belohnungen, Erfahrung usw. erlangen. Diese Events beginnen und enden zu einem bestimmten Zeitpunkt.`,
  me = `Wählen Sie die Art des Events`,
  he = `Herausforderung oder Wettbewerb`,
