  ye = `Sonderevents für „%1$s“`,
  be = `Sie können diese Eventart dazu verwenden, damit Ihr Spiel während dieses Events auf besondere Weise hervorgehoben wird. Klicken Sie auf die Schaltfläche unten, um weitere Informationen zur Funktionsweise dieser Eventarten während des Events „%1$s“ zu erhalten.`,
