  De = `Spielupdate – in den meisten Spielen aktualisiert sich das Spiel selbst mit neuen Inhalten und Änderungen.`,
  Oe = `Große Veröffentlichung – kündigen Sie das Veröffentlichungsdatum des Spiels oder der Zusatzinhalte an.`,
