  ft = `Als Supportmitarbeiter von Valve können Sie diese Schutzeinstellung umgehen. Die Änderung eines veröffentlichten Events wird der maximal erlaubten Anzahl nicht angerechnet. Bitte beachten Sie dies bei einer solchen Änderung.`,
  pt = `Sie können maximal %1$s dieser Eventarten veröffentlichen und haben das Limit bereits erreicht.`,
