  _t = `Steam-Spielevorschau: Kurzpräsentation`,
  vt = `Verwenden Sie diese Präsentation, um Steam-Kunden interessante Details zu Ihrem Entwicklerteam, zu Ihrer Demo und deren Bezug zu Ihrem Spiel mitzuteilen. Insofern angegeben, wird die Kurzpräsentation auf Ihrer Steam-Shopseite und zusammen mit Ihrem Spiel auf den entsprechenden Seiten der Spielevorschau angezeigt.`,
  yt = `Steam-Spielevorschau: Livestream`,
  bt = `Wählen Sie einen Zeitpunkt, zu dem Fans sich einen Livestream zu Ihrem Spiel ansehen und Ihnen Fragen stellen können. Dieses Event erscheint im offiziellen Kalender der Steam-Spielevorschau und wird automatisch auf Ihrer Spielseite angezeigt.`,
  xt = `Steam-Spielevorschau: Sprechzeiten`,
  St = `Wählen Sie einen Zeitpunkt aus, an dem Ihr Team und Sie für Ihre Fans erreichbar sind, sodass diese Fragen an Sie stellen und mit Ihnen chatten können. Sie können einen beliebigen Zeitpunkt und Ort auswählen\xA0– sei es im Steam Chat, auf Discord, Reddit-AMA oder an anderer Stelle.`,
