  Mt = `Seitenabrufe: %1$s`,
  Nt = `Seitenaufrufe: %1$s`,
  Pt = `Das Event-Zeitplan-Widget ermöglicht es der Aktionsseite, einen Browser für bevorstehende Events einzubetten. Es gibt auf der Aktionsseite hervorgehobenen Spielen zusätzliche Sichtbarkeit und belohnt Kommunikation mit dem Steam-Publikum während der Aktion über erstellte Spiel-spezifische Events. Beispielsweise sind Übertragungen und Chats Möglichkeiten, über die Entwickler mit ihrem Steam-Publikum kommunizieren können.`,
  Ft = `Bitte wählen Sie mindestens eine Eventart für den Zeitplan aus.`,
  It = `Wählen Sie ein Anfangs- und Enddatum für den Zeitplan. Diese können mit dem Beginn und Ende Ihres Events übereinstimmen oder Sie können andere Daten angeben, wenn bei diesem Event ein zukünftiger Zeitplan angekündigt wird.`,
  Lt = `Standardmäßig verfügen Aktionsseiten über einen %1$s, bei dem es sich um die Quelle von Events handelt. Dieser ist für die Admins der Aktion sofort sichtbar und für alle, sobald diese Aktionsseite sichtbar ist.`,
  Rt = `News-Hub`,
  zt = `%1$s Eventart ist aktiv`,
  Bt = `%1$s Eventarten sind aktiv`,
  Vt = `Demos im Widget vorstellen`,
  Ht = `Wenn aktiviert, wird die Aktion „Demo spielen“ bevorzugt, wenn Details des Spiels bereitgestellt werden bzw. die Maus über Aktionen gezogen wird. Dies taucht auch während des Events zur Demoveröffentlichung innerhalb des Zeitraums im Zeitplan auf.`,
  Ut = `Als Startzeit des Events festlegen`,
  Wt = `Als Ende des Events festlegen`,
  Gt = `Inbegriffene Events:`,
  Kt = `Erlauben Sie, dass alle qualifizierten Events der hervorgehobenen Anwendungen im Zeitplan erscheinen.`,
  qt = `Der Zeitplan führt immer alle qualifizierten Events der Basisgruppe und alle Events einer Serie auf. Wenn Sie dieses Kästchen markieren, werden die qualifizierten Events aller vorgestellten Anwendungen ebenfalls im Zeitplan angezeigt. Wenn Sie diese Auswahl aufheben, werden nur Events angezeigt, die entweder mit einer Hosting-Community-Gruppe verknüpft oder explizit in einer Serie aufgeführt sind.`,
  Jt = `Achtung: Der geplante Beginn liegt vor dem Beginn des Events. Sind Sie sicher, dass dies richtig ist?`,
  Yt = `Sind Sie sicher?`,
  Xt = `Sind Sie sicher? Alle nicht gespeicherten Änderungen gehen verloren.`,
