  cn = `Nicht gelistet und sichtbar`,
  ln = `Steam-Nutzer können dieses Event mit einem direkten Link sehen. Die Sichtbarkeit des Events kann nicht rückgängig gemacht werden. Sie können das Event nur löschen, falls Sie es wirklich verstecken müssen.`,
