  pn = `Dieses Event ist veröffentlicht, aber bis zum angegebenen Zeitpunkt versteckt. Es sind keine weiteren Schritte erforderlich. Das Event wird zum angegebenen Zeitpunkt automatisch für Ihre Steam-Kunden sichtbar.`,
  mn = `Dieses Event wird zum Startzeitpunkt automatisch sichtbar.`,
  hn = `Dieses Event wird automatisch vor dem Startzeitpunkt sichtbar: %1$s`,
  gn = `Diese Events sind für die Zukunft geplant, werden aber erst zum Startzeitpunkt sichtbar. Es sind keine weiteren Schritte erforderlich. `,
  _n = `Versteckt, nicht veröffentlicht`,
  vn = `Dieses Event ist ein Entwurf und nur für Mitglieder Ihres Communityteams sichtbar. Alle Änderungen bleiben bis zur Veröffentlichung des Events versteckt.`,
  yn = `Nach RSS-Feed veröffentlicht. Klicken, um die RSS-Administration zu öffnen.`,
