  or = `Willkommen!`,
  sr = `<1>Ihre Spiele:</1> Ihre Spiele erscheinen unten in der Liste verknüpfter Anwendungen und sind sofort einsatzbereit. Sie können dort ebenfalls Bereiche hinzufügen und konfigurieren, um Ihre Spiele, Zusatzinhalte, Demos und Soundtracks optimal zu präsentieren.`,
  cr = `<1>Weitere Spiele verknüpfen:</1> Falls in der folgenden Liste Spiele fehlen, haben Sie diese nicht mit der Erstellerseite verknüpft. Anweisungen zum Verknüpfen von Spielen finden Sie in unserer Dokumentation zu <2>Entwickler- und Publisherseiten</2>.`,
  lr = `<1>Standardkonfiguration:</1> Unten finden Sie eine Reihe von Standardbereichen, die bereits vorkonfiguriert sind, um Ihre beliebtesten, empfohlenen und neuesten Veröffentlichungen hervorzuheben. Sie können die Standardkonfiguration nach Belieben anpassen.`,
