  gr = `Diese Aktion umfasst eine große Liste verknüpfter Inhalte, deren Tags über den Shop wiederhergestellt werden müssen. Dies kann einen Moment dauern.`,
  _r = `Die Aktions-Tags der Inhalte konnten über den Shop nicht wiederhergestellt werden. Der Editor kann daher nicht sicher geöffnet werden. Bitte laden Sie die Seite neu, um es erneut zu versuchen.`,
  vr = `%1$s Inhalte aus der Liste verknüpfter Inhalte konnten nicht über den Shop abgerufen werden, da diese höchstwahrscheinlich gesperrt wurden oder nicht länger zum Kauf angeboten werden. Die zugehörigen Tags konnten nicht wiederhergestellt werden und die Inhalte werden somit ggf. nicht in den gefilterten Bereichen angezeigt: %2$s. (Sie können wie gewohnt weiterarbeiten, wenn die Inhalte gesperrt sind.) `,
  yr = `Start des Events`,
  br = `Ankündigungsdatum`,
