  wr = `Zukunft – planen Sie die Veröffentlichung dieser Ankündigung`,
  Tr = `Geplanter Start`,
  Er = `Geplantes Veröffentlichungsdatum`,
  Dr = `Sie können das Event schon vor dem Startdatum sichtbar machen, um Ihre Spieler im Vorfeld darüber zu informieren und Ihnen die Gelegenheit zu geben, sich für Benachrichtigungen anzumelden.`,
  Or = `Sie können die Ankündigung schon vor dem Startdatum sichtbar machen, um Ihre Spieler im Vorfeld darüber zu informieren und Ihnen die Gelegenheit zu geben, sich für Benachrichtigungen anzumelden.`,
  kr = `Ende des Events`,
  Ar = `Events dieser Kategorie haben üblicherweise ein Ende.`,
  jr = `Wählen Sie ein Enddatum aus, damit Steam Ihr Event rechtzeitig als beendet anzeigt. Steam kann dadurch die Anzeige Ihrer anderen Events priorisieren, die zurzeit aktiv oder neuer sind.`,
  Mr = `Endet nach einem bestimmten Zeitraum nach dem Startzeitpunkt.`,
  Nr = `Wir runden den Endzeitpunkt auf: %1$s`,
  Pr = `Endzeitpunkt`,
  Fr = `Eventzeiten werden sowohl im Editor als auch für Steam-Kunden in der lokalen Zeitzone angezeigt.`,
