  Lr = `Geben Sie die Zeit Ihrer Zeitzone an. Diese wird automatisch in die Zeitzone des jeweiligen Besuchers umgewandelt und angezeigt.`,
  Rr = `Automatische Erinnerungen`,
  zr = `Wenn Sie den Startzeitpunkt des Events in die Zukunft setzen UND das Event früher sichtbar machen, können sich Fans an den Eventbeginn erinnern lassen. Steam sendet Steam-Nutzern, die sich dafür angemeldet haben, automatisch eine Push-Benachrichtigung und/oder eine E-Mail.`,
  Br = `Dieser Test sendet die Benachrichtigung nur an Ihren Account, wenn Sie über eine verifizierte E-Mail verfügen und/oder %1$s installiert haben.`,
