  Gr = `App-ID mit diesem Event verknüpfen?`,
  Kr = `Ermöglicht die Verknüpfung einer App-ID mit dem Event. Hierdurch erscheint die Shopkapsel automatisch am Ende der angezeigten Eventbeschreibung. Bei Bedarf werden Anwendungsinformationen an andere Widgets, beispielsweise für Übertragungen oder Zeitpläne, weitergegeben.`,
  qr = `Start:`,
