  oi = `Branch auswählen`,
  si = `Wählen Sie den Branch aus, mit dem Sie das Event assoziieren möchten. Dieses Event wird dann mit dem aktuellen Build dieses Branches assoziiert. Sie können die Verknüpfung eines Events mit einem Build auch auflösen, indem Sie die Option „Dieses Event mit keinem Build assoziieren“ auswählen.`,
  ci = `Standard-Branch („default“): Build „%1$s“ (%2$s)`,
