  vi = `Eventverlauf (die letzten 100 Einträge)`,
  yi = `Unten finden Sie eine Liste der jüngsten Änderungen, die an diesem Event vorgenommen wurden. Sie können eine Version auswählen und auf diese zurücksetzen, wenn Sie die Änderungen rückgängig machen möchten.`,
  bi = `Unterschiede zur letzten Version`,
