  Ai = `Für Übertragungen`,
  ji = `Falls ein Steam-Kunde in den Account-Einstellungen „Übertragungen im Shop ausblenden“ ausgewählt hat, wird auch dieser Bereich versteckt, da dessen Rendering sich spezifisch auf den übertragenen Inhalt bezieht.`,
  Mi = `Verbergen, wenn die Übertragung deaktiviert ist`,
