  Gi = `Unten HTML eingeben oder einfügen.`,
  Ki = `Zeilenumbrüche beibehalten`,
  qi = `In HTML haben Zeilenumbrüche normalerweise keine Auswirkung, aber in BBCode werden sie als leere Zeilen angezeigt. Wenn Sie die Tags <p> oder <br> verwendet haben, lassen Sie diese Option deaktiviert. Wenn Sie Blog-Software verwenden, die automatisch <br>-Tags für Zeilenumbrüche hinzufügt, empfiehlt es sich, dieses Kontrollkästchen zu markieren.`,
