  ha = `Vorschau unten anzeigen`,
  ga = `Vorschau jetzt aktualisieren`,
  _a = `Automatisch aktualisieren`,
  va = `Vorschau:`,
  ya = `Diese Eventart wird automatisch zum bei der Einrichtung vorgegebenen Zeitpunkt veröffentlicht und darf NICHT vor dem Beginn des Events veröffentlicht werden.`,
  ba = `Wenn Sie das Event veröffentlichen, werden alle ausstehenden Änderungen gespeichert und das Event wird entsprechend der Sichtbarkeitseinstellung sichtbar gemacht.`,
  xa = `Als nicht gelistet veröffentlichen`,
  Sa = `Durch die Veröffentlichung werden alle Änderungen gespeichert und das Event ist für alle Personen sichtbar, die über einen Link darauf zugreifen können. Dieses Event wird nicht in Event-Listen angezeigt, ist aber für Kunden mit dem entsprechenden Link einsehbar.`,
  Ca = `Veröffentlichen`,
  wa = `Durch die Veröffentlichung werden alle Änderungen gespeichert und die Erstellerseite ist für alle Personen sichtbar, die über einen Link darauf zugreifen können. Dies gilt auch für Kunden, die Zugriff auf den entsprechenden Link haben. Um diese Seite zu Ihrer Erstellerseite zu machen, müssen Sie sie nach ihrer Veröffentlichung noch freischalten.`,
  Ta = `Alle Änderungen speichern und dieses Event veröffentlichen?`,
  Ea = `Das Event wird sofort öffentlich sichtbar.`,
  Da = `Das Event bleibt bis zum Startzeitpunkt (%1$s) versteckt und wird dann automatisch öffentlich sichtbar.`,
  Oa = ` Sie können die Inhalte des Events nach der Veröffentlichung weiterhin bearbeiten.`,
  ka = `Hinweis: Sobald das Event veröffentlicht ist, können Sie es nicht wieder in den Status „Nicht veröffentlicht“ zurücksetzen.`,
  Aa = `Möchten Sie jetzt alle Änderungen speichern und diese Seite veröffentlichen?`,
  ja = `Die Seite ist erst sichtbar, wenn sie im Dashboard für die Startseite aktiviert wurde.`,
  Ma = `Sie können diese Seite nach der Veröffentlichung weiterhin bearbeiten.`,
  Na = `Benutzerdefinierte Veröffentlichungszeit`,
  Pa = `Die benutzerdefinierte Veröffentlichungszeit muss zwischen jetzt und dem Startzeitpunkt des Events liegen.`,
  Fa = `Nur für benutzerdefinierte Veröffentlichungszeit`,
  Ia = `Das Event kann nicht veröffentlicht werden, ohne zuvor gespeichert zu sein.`,
  La = `Veröffentlichung erst nach Genehmigung durch Valve möglich.`,
  Ra = `Bitte reichen Sie Ihr Spiel mindestens sieben Tage vor Ihrem gewünschten Veröffentlichungsdatum zur Überprüfung ein. Nutzen Sie dafür die Schaltfläche auf der rechten Seite. Ein Zeitraum von mindestens sieben Tagen stellt sicher, dass genug Zeit für das Genehmigungsverfahren und ggf. für erforderliche Änderungen vorhanden ist`,
  za = `Interner Fehler im Editor. Der lokalisierte Text wurde nicht geladen. Speichern/Veröffentlichen wird blockiert, um Datenverlust zu verhindern.`,
  Ba = `Hinweis: Der Inhalt des Events oder der Ankündigung wurde von Nutzer %2$s zu diesem Zeitpunkt geändert: %1$s. Die von Ihnen aktuell bearbeitete Version stammt von: %3$s. Möchten Sie diese Änderungen überschreiben?`,
  Va = `Möchten Sie die Änderungen überschreiben?`,
  Ha = `Veröffentlichung fehlgeschlagen`,
  Ua = `Mit Warnungen veröffentlichen`,
  Wa = `Status`,
  Ga = `Bitte warten, Veröffentlichungsvorgang läuft\xA0…`,
