  Ya = `Bis zu folgendem Zeitpunkt verstecken:`,
  Xa = `Dies bedeutet, dass Steam-Kunden dieses Event sofort nach Veröffentlichung sehen können. Dies ist die standardmäßige Auswahl für Ankündigungen oder neue Funktionen.`,
  Za = `Dies bedeutet, dass das Event bis zum Start des Events versteckt bleibt und dann automatisch sichtbar wird.`,
  Qa = `Nach der Veröffentlichung Ihres Events bleibt es bis zum angegebenen Zeitpunkt versteckt. So können Sie mehrere zukünftige Events planen, die dann automatisch zum festgelegten Zeitpunkt erscheinen und Ihre Kunden fortlaufend über interessante Aktivitäten informieren.`,
  $a = `Versteckt`,
