  ro = `Dieses Event wird automatisch sichtbar: %1$s`,
  io = `Es sind keine weiteren Schritte erforderlich.`,
  ao = `Wenn Sie das Event speichern, bleibt es weiterhin versteckt. Um das Event für Ihre Steam-Kunden sichtbar zu machen, müssen Sie es veröffentlichen.`,
  oo = `Alle an diesem Event vorgenommenen und gespeicherten Änderungen werden Ihren Steam-Kunden angezeigt.`,
  so = `Unbenannt`,
  co = `Fehler beim Parsen des BBCodes`,
  lo = `Beim Parsen des BBCodes in Ihrem Ankündigungstext für die Vorschau ist ein Fehler aufgetreten: %1$s`,
  uo = `Dieses Event ist veröffentlicht. Es beginnt am %1$s und wird zu diesem Zeitpunkt für Spieler sichtbar.`,
