  po = `Dieses Event ist veröffentlicht. Der Startzeitpunkt eines veröffentlichten Events kann nicht geändert werden.`,
  mo = `Dieses Event hat am %1$s geendet. Der Endzeitpunkt kann nicht mehr geändert werden.`,
