  go = `Dieses Event wurde um %1$s sichtbar und beginnt um %2$s`,
  _o = `Dieses Event wird um %1$s sichtbar und beginnt um %2$s`,
  vo = `Dieses Event ist sichtbar und beginnt um %1$s`,
  yo = `Dieses Event ist sichtbar und begann um %1$s`,
  bo = `Dieses Event wurde veröffentlicht und ist seit %1$s sichtbar`,
  xo = `Bearbeiten/Migrieren`,
  So = `Diese Ankündigung wurde in einer älteren Version des Ankündigungssystems erstellt. Daher sind die neuen Kategorien, Titel-Artwork und Endzeitpunkt nicht verfügbar. Wenn Sie die Ankündigung bearbeiten und speichern, wird sie in das neue System migriert und unterstützt anschließend die genannten Funktionen.`,
  Co = `Hierdurch werden das Event und alle damit zusammenhängende Metadaten (Bewertungen, Kommentare, Statistiken) von Steam gelöscht. Falls das Event bereits sichtbar ist, leitet es auf eine leere Seite weiter und wird Kunden nicht mehr empfohlen. Dies kann nicht rückgängig gemacht werden.`,
  wo = `Hier wird das Event so angezeigt, wie es Steam-Kunden sehen werden. In dem kleinen Vorschaubalken oben können Sie die Sprache ganz leicht ändern.`,
  To = `Dieses Event ist mit Ihrer Erstellerseite verknüpft: `,
