  No = `Datum/Zeit liegt nach der erlaubten Endzeit (%1$s).`,
  Po = `Der Zeitraum wurde von %1$s blockiert. Sie können kein Event einplanen, das innerhalb des blockierten Zeitraums beginnt oder endet. Auch ist es nicht möglich, ein Event einzuplanen, das vor dem blockierten Zeitraum beginnt und danach endet.`,
  Fo = `Der Zeitraum wurde von %1$s blockiert; Grund: %2$s. Sie können kein Event einplanen, das innerhalb des blockierten Zeitraums beginnt oder endet. Auch ist es nicht möglich, ein Event einzuplanen, das vor dem blockierten Zeitraum beginnt und danach endet.`,
  Io = `Zeitzone`,
  Lo = `Verwenden Sie bitte Ihre lokale Zeitzone, wenn Sie Datum und Uhrzeit eingeben. Die Zeit wird automatisch in die lokale Zeit des Steam-Benutzers konvertiert, wenn dieser die Seite des Events/der Ankündigung aufruft.`,
  Ro = `Hoppla! Der Endzeitpunkt des Events kann nicht vor dem Startzeitpunkt liegen.`,
  zo = `Startzeitpunkt liegt in der Vergangenheit`,
  Bo = `Startdatum und -zeitpunkt liegen früher als erlaubt.`,
