  Ho = `Enddatum und -zeitpunkt liegen später als erlaubt.`,
  Uo = `Kurzbeschreibung`,
  Wo = `(Max. %1$s Zeichen. Erscheint in der Eventliste.)`,
  Go = `(Max. Anzahl von %1$s Zeichen erreicht. Erscheint in der Eventliste.)`,
  Ko = `Bis zu %1$s Zeichen lang ohne BBCode. Diese Kurzbeschreibung erscheint in der Steam-Bibliothek und ist optional. Wenn nicht angegeben, wird sie automatisch aus dem ersten Absatz der Eventbeschreibung generiert.`,
  qo = `Optional: Verfassen Sie eine Zusammenfassung des Events in bis zu %1$s Zeichen. Ansonsten wird diese automatisch generiert.`,
  Jo = `Automatisch generierte Zusammenfassung: `,
  Yo = `%1$s Zeichen verbleibend`,
  Xo = `Der Titel des Events kann bis zu %1$s Zeichen lang sein. Im Titel wird BBCode nicht unterstützt.`,
  Zo = `Der Titel dieser Seite dient nur als Vorlage. Er wird ausschließlich auf Ihrem Dashboard angezeigt.`,
  Qo = `Der Untertitel darf bis zu %1$s Zeichen lang sein und nur Text enthalten (BBCode wird nicht unterstützt). Er wird gemeinsam mit dem Titel auf der Event- oder Ankündigungsdetailseite verwendet.`,
  $o = `Die Kurzbeschreibung darf bis zu %1$s Zeichen lang sein und nur Text enthalten. Sie erscheint unterhalb des Titels in einer Liste von Events oder im Event-Spotlight. Wenn keine Kurzbeschreibung angegeben ist, generiert Steam sie automatisch für jede Sprache aus dem Text am Anfang der Beschreibung.`,
  es = `Optionen`,
  ts = `Besondere Hervorhebung bei größeren Events`,
  ns = `Wo soll das Event außerdem auftauchen?`,
  rs = `Sichtbarkeit`,
  is = `Sichtbarkeitsoptionen für dieses Event`,
  as = `Startseite`,
  os = `Erstellerseite`,
  ss = `Auch im Workshop veröffentlichen`,
  cs = `Ist dieser Beitrag für Besucher Ihres Steam Workshop relevant?`,
  ls = `Auch auf der Demodetailseite in der Bibliothek veröffentlichen`,
  us = `Ist dieser Beitrag für die Spieler Ihrer Demo relevant?`,
  ds = `Als angesagtes Event auf der Spieldetailseite in der Bibliothek anzeigen`,
  fs = `Bevor wir ein Spotlight aktivieren können, stellen Sie bitte sicher, dass im Tab „%1$s“ zumindest ein englisches Spotlight-Bild vorhanden ist.`,
  ps = `Automatischen Text anzeigen?`,
  ms = `Titel und Untertitel des Events, sowie ein zu Schwarz übergehendes Overlay, werden automatisch über der rechten oberen Ecke des Bildes anzeigt.`,
  hs = `Dieses Event wird vorübergehend für jeden Benutzer oberhalb des Aktivitätsbereichs angezeigt. Dies sollte nur für größere Events und mit ausreichend Zeit zwischen den Events verwendet werden, sodass nicht immer ein Event auf Ihrer Spieldetailseite angezeigt wird.`,
  gs = `Im Bereich „Was ist neu?“ anzeigen`,
  _s = `Je nach Spielzeit und einigen anderen Faktoren wird Ihr Beitrag Spielern im Bereich „Was ist neu?“ in der Steam-Bibliothek angezeigt.`,
  vs = `Auf der Spieldetailseite anzeigen`,
  ys = `Auf der Steam-Shopseite anzeigen`,
  bs = `Denken Sie sorgfältig darüber nach, welche Inhalte Sie Steam-Nutzern zeigen möchten, unabhängig davon, ob diese Ihr Spiel in ihrer Bibliothek haben oder Ihre Produktseite aufrufen. Ein Link zu einem anderen Online-Store, in dem Sie Ihr Spiel anbieten, ist beispielsweise nicht gestattet. Befolgen Sie bitte bei allen Beiträgen die %1$s.`,
  xs = `Allgemeine Regeln auf Steam`,
  Ss = `Auf der Bibliotheksstartseite verstecken`,
  Cs = `enthält nicht jugendfreie Inhalte`,
  ws = `Setzen Sie diese Einstellung, wenn der Beitrag explizit sexuelle Bilder oder andere Inhalte umfasst, und ist nur für Anwendungen verfügbar, die als „nicht jugendfrei“ markiert wurden.`,
  Ts = `Auf der Spieldetailseite verstecken`,
