  jh = `Die hier angegebene Zahl gibt die geschätzte Anzahl von Besuchern Ihrer Shopseite für die Dauer des Events an.`,
  Mh = `Shop: auf der Seite „Kürzlich aktualisierte Spiele“`,
  Nh = `Wenn Sie nach Veröffentlichung dieses Events eine Produktupdate-Sichtbarkeitsrunde verwenden, erscheint es Spielern, die Ihr Spiel besitzen oder auf der Wunschliste haben, auf der Seite „Kürzlich aktualisiert“.`,
  Ph = `Die hier angegebene Zahl entspricht der Anzahl von Nutzern, die Ihr Spiel besitzen oder auf der Wunschliste haben und das Event auf der Seite „Kürzlich aktualisiert“ sehen können.`,
  Fh = `Neuigkeiten: auf der Neuigkeitenseite Ihres Spiels`,
