  Uh = `In Zukunft:`,
  Wh = `Bibliothek: auf der Steam-Bibliotheksstartseite (eventuell)`,
  Gh = `Dieses Event erscheint Spielern oben auf ihrer Bibliotheksstartseite, abhängig von der Anzahl anderer Spiele, die ein bestimmter Spieler besitzt, und der relativen Priorität jeder Ankündigung bzw. jedes Updates.`,
