  qh = `Bibliothek: Spotlight-Banner auf der Bibliotheksseite Ihres Spiels`,
  Jh = `Bei Angabe eines Spotlight-Bannerbilds erscheint Ihr Event/Ihre Ankündigung unterhalb der Schaltfläche „Spielen" auf Ihrer Spieldetailseite in der Steam-Bibliothek.`,
  Yh = `Bibliothek: auf Ihrer Spielseite in der Steam-Bibliothek`,
  Xh = `Ihr Event erscheint im Abschnitt „Aktivität“ auf Ihrer Spielseite in der Steam-Bibliothek von Nutzern.`,
  Zh = `Basierend auf der Anzahl an Spielern, die Ihr Spiel besitzen und es in ihrer Steam-Bibliothek sehen können.`,
  Qh = `Auf der Workshop-Seite`,
  $h = `Sie haben die Möglichkeit, Ihre Ankündigung/Ihr Event auch im Workshop zu veröffentlichen. Rufen Sie dazu die Option „auch im Workshop veröffentlichen“ im Tab „Optionen“ aus. Standardmäßig werden Ankündigungen nicht im Workshop veröffentlicht.`,
  eg = `Steam-Produktseitenbanner (Aktion)`,
  tg = `Produktseitenbanner wird vom %1$s bis zum %2$s angezeigt.`,
  ng = `Sie haben die Möglichkeit, im Tab für Aktionen ein spezielles Banner hinzuzufügen. Dieses Banner erscheint dann auf den Steam-Produktseiten der an der Aktion teilnehmenden Spiele, und ermöglicht vorgestellten Titeln, wieder auf die Aktionsseite zurückzuverweisen. So werden Steam-Kunden beim Stöbern im Shop oder über eine Wunschlisten-E-Mail ebenfalls über die Rabattaktion informiert. Aktionsbanner werden nur für die Dauer Ihres Events oder für maximal zwei Wochen angezeigt. Anfangs- und Endzeitpunkt für Ihre Rabattaktion werden im Tab „Optionen“ festgelegt.`,
  rg = `Benachrichtigungen: E-Mails an Spieler, die Ihrem Spiel oder Ihrer Entwickler-/Publisherseite folgen`,
  ig = `Dies schließt alle Follower der mit diesem Spiel verknüpften Entwickler-, Publisher- und Franchiseseiten mit ein.`,
  ag = `Die folgenden Entwickler-, Publisher- und Franchiselinks haben keine sichtbare Erstellerseite. Richten Sie eine Erstellerseite ein, um Ihre Angebote zu erläutern und Kunden die Gelegenheit zu geben, mehr über Ihre Events und neue Spielveröffentlichungen zu erfahren: %1$s`,
  og = `Neuigkeiten: Benutzerdefinierte Eventkalender`,
  sg = `Das Event erscheint im personalisierten News-Hub von Spielern, die Ihr Spiel in ihrer Bibliothek oder auf ihrer Wunschliste haben, oder Ihrem Spiel folgen.`,
  cg = `Benachrichtigungen: Push-Nachrichten an für diese angemeldete Spieler senden`,
  lg = `Die Anzahl der Spieler, die sich explizit für eine Erinnerung für dieses Event angemeldet haben (indem sie einen externen Kalendereintrag heruntergeladen haben oder diesem Event folgen).`,
  ug = `Spieler, die eine E-Mail erhalten`,
  dg = `Geschätzte Anzahl an E-Mails, die dieses Event erwähnen. Wir senden Kunden regelmäßig eine E-Mail mit einer Zusammenfassung relevanter Events. Dies hängt von den E-Mail-Einstellungen und Kommunikationseinstellungen der Kunden ab.`,
  fg = `Spieler, die Marketingnachrichten erhalten`,
  pg = `Geschätzte Anzahl der Spieler, denen dieses Event in ihrer benutzerdefinierten Steam-Client-Marketingnachricht angezeigt wird. Dies ist ein Pop-up, das sich beim Start des Steam-Clients öffnet und auf relevante Steam-Angebote und interessante Eventinformationen hinweist.`,
  mg = `Spieler, die dieses Event ignorieren`,
  hg = `Die Anzahl der Spieler, die dieses Event explizit ignorieren.`,
  gg = `Fehler beim Laden des Events`,
  _g = `Zur Dokumentation`,
  vg = `Marketingnachricht zu einem großen Update – Überprüfung`,
  yg = `Nachdem ein Event zur Ankündigung in einer Marketingnachricht eingerichtet ist und keine weiteren Änderungen erforderlich sind, muss es zur Überprüfung eingereicht werden. Die Überprüfung und Genehmigung kann bis zu %1$s Werktage in Anspruch nehmen. Anschließend können Sie das Event jederzeit veröffentlichen.`,
  bg = `Beginnen Sie das Prüfverfahren über die folgende Anfrage.`,
  xg = `Anfrage auf Überprüfung erstellen`,
  Sg = `Anfrage auf Überprüfung eingereicht. Sie können den Status <1>hier</1> einsehen und Informationen aktualisieren.`,
  Cg = `Übersicht`,
  wg = `Sichtbar machen`,
  Tg = `Dieser Inhalt wird mit der Veröffentlichung an den meisten Orten sofort sichtbar.`,
  Eg = `Hinweis: Neue Beiträge werden vor der Veröffentlichung von unserem Moderationsteam überprüft. Es kann eine (1)\xA0oder mehrere Stunden dauern, bis Ihre Neuigkeiten oder Events in der Steam-Bibliothek erscheinen. Jegliche Änderungen an bestehenden Beiträgen schieben Ihren Beitrag in der Moderationswarteschlange weiter zurück.`,
  Dg = `oder Inhalte des bestehenden Events ersetzen`,
  Og = `(Ungewöhnlich) Mit dieser Option können Sie eine Vorschau der Aktualisierungen in einem „Entwurf“ des Events erstellen und anschließend den Inhalt eines veröffentlichten Events mit dem Inhalt dieses Events ersetzen. Dieses Event wird gelöscht und ersetzt den Inhalt des ausgewählten, bereits veröffentlichten Events. Bitte beachten Sie, dass die Eventart und die Sichtbarkeitseinstellungen des Zielevents nicht aktualisiert werden.`,
  kg = `Dieses Event wurde von „%1$s“ dupliziert`,
