  t_ = `Veraltet: VOD-Pipeline ist jetzt deaktiviert, bleibt jedoch verfügbar, für den Fall, dass ein altes Video verwendet werden muss. Dieses Video wird vor der normalen Übertragungszeit im Player angezeigt. VOD muss über öffentliche Berechtigungen verfügen (unabhängig vom Veröffentlichungsstatus).`,
