  PS = `Produktschlüssel hochladen`,
  FS = `Steam-Produktschlüssel generieren`,
  IS = `Berechtigt, Steam-Produktschlüssel für Ihre Anwendung anzufordern und Produktschlüssel von Drittanbietern hochzuladen.`,
  LS = `Finanzinformationen einsehen`,
