  uD = `Spiele pro Seite`,
  dD = `Wenn der Wert auf null gesetzt wird, wird auf einen angemessenen Standardwert (12 Artikel) zurückgegriffen. Andernfalls wird versucht, die festgelegte Anzahl an Anwendungen pro Seite zu laden, bevor die Schaltfläche „Mehr anzeigen“ angezeigt wird.`,
  fD = `Tabs`,
