  hD = `Zusätzliche Tabs, die zur Ansicht hinzugefügt werden können, aber ansonsten nicht in dieser Komponente verwendet werden.`,
  gD = `Events: %1$s`,
  _D = `< Bitte wählen Sie eine Kategorie >`,
  vD = `Anwendungen und Bündel`,
  yD = `Dieser Bereich dient dazu, Spiele, Pakete und Bündel auf Ihrer Seite anzuzeigen. Sie können mehrere dieser Bereiche erstellen, um jeweils eine andere Auswahl an Spielen anzubieten.`,
  bD = `Spiele, Zusatzinhalte und Demos`,
  xD = `Dieser Bereich dient dazu, Spiele auf Ihrer Seite anzuzeigen. Sie können mehrere dieser Bereiche erstellen, um jeweils eine andere Auswahl an Spielen anzubieten.`,
  SD = `Neuigkeiten und Events`,
  CD = `Zeigt gezielt ausgewählte Steam-Events und -Ankündigungen auf Ihrer Seite an.`,
  wD = `Bilder`,
  TD = `Zeigt ein oder mehrere Bilder, die als einzelner Inhalt, Karussell oder Raster angezeigt werden. Optional können lokalisierte Bilder bereitgestellt und mit anderen Bereichen im Shop verknüpft werden.`,
  ED = `Zeigt ein oder mehrere Bilder, die als einzelnes Element, Karussell oder Raster angeordnet werden. Optional können lokalisierte Bilder bereitgestellt werden.`,
  DD = `Titelbild des Spiels`,
  OD = `Zeigt eine einzige lokalisierbare Grafik als Titelbild an.`,
  kD = `Seite für übergreifende Werbeaktionen`,
  AD = `Dieses Widget ruft automatisch Spiele von einer verwandten, gleichzeitig live-geschalteten Aktionsseite ab. Bitte stellen Sie sicher, dass die Inhalte dem Thema Ihrer Aktionsseite entsprechen.`,
  jD = `Player`,
  MD = `Wenn auf dieser Seite Übertragungen aktiviert sind, erscheint der Video-Player standardmäßig oben auf der Seite. Über dieses Widget können Sie einstellen, wo der Übertragungs-Player innerhalb der Seite erscheint.`,
  ND = `Eventbeschreibung`,
  PD = `Fügt den Text aus dem Tab „Beschreibung“ hinzu, der dann hier auf der Seite erscheint.`,
