  LD = `Text`,
  RD = `Zeigt einen Textbereich an, der Formatierungen, Bilder und Videos unterstützt.`,
  zD = `Widget für Entwickler-/Publisherstartseite oder Communitygruppe`,
  BD = `Dies zeigt ein Widget mit dem Namen, der Beschreibung und einer Schaltfläche zum Abonnieren der betreffenden Steam-Communitygruppe oder Entwickler-/Publisherstartseite an.`,
  VD = `Kurator: %1$s`,
  HD = `Spieltrailerkarussell`,
  UD = `Eine große Traileranzeige, die zunächst einen Mikrotrailer abspielt, gefolgt vom Haupttrailer des Shops. Informationen zum Spiel erscheinen auf der rechten Seite.`,
  WD = `Anwendungen werden in diesem Bereich nur angezeigt, wenn es für sie einen Trailer gibt.`,
  GD = `Einzelne Erstellerliste anzeigen`,
  KD = `Zeigt ein Karussell der Erstellerlisten an, wie unter Einstellungen im Abschnitt „Listen verwalten“ Ihrer Erstellerseite definiert.`,
  qD = `Alle Erstellerlisten anzeigen`,
  JD = `Zeigt ein Karussell aller Erstellerlisten an, wie unter Einstellungen im Abschnitt „Listen verwalten“ Ihrer Erstellerseite definiert.`,
  YD = `Empfehlungen und Listen von Kuratoren`,
  XD = `Dies steuert, wo auf der Seite die Empfehlungen von Kuratoren oder Vorstellungslisten erscheinen. Standardmäßig sehen Nutzer, die Steam-Kuratoren folgen, unten auf der Seite deren Empfehlungen zu in der Aktion vorgestellten Spielen. Hiermit legen Sie fest, wo dieser Bereich erscheinen kann.`,
  ZD = `Zeigt Kuratorenempfehlungen und -listen an. Ruft Listen automatisch von Listen der Kuratoren ab, denen Steam-Nutzer folgen sowie denen, die in Ihrer hervorgehobenen Kuratorliste stehen und in der vom Steam-Nutzer ausgewählten Sprache verfasst sind.`,
  QD = `Startzeit der Empfehlungen anzeigen (optional)`,
  $D = `Legen Sie eine Startzeit fest (optional), ab welchem Zeitpunkt Empfehlungen angezeigt werden. Dies gibt Kuratoren die Möglichkeit, ihre Listen zusammenzustellen, bevor diese sichtbar werden. Die Startzeit muss zwischen Eventbeginn und -ende liegen.`,
  eO = `Empfehlungslisten von Kuratoren:`,
  tO = `(Optional) Wählen Sie unter den für diese Aktion von Kuratoren zusammengetragenen Listen aus. Kuratoren können diese Listen erst nach Beginn der Aktion erstellen.`,
  nO = `Liste auswählen und anzeigen`,
  rO = `Kuratoren können eine Liste von bestimmten Spielen erstellen, die an der Aktion teilnehmen. Optional können Sie über dieses Dialogfeld eine oder mehrere Listen auswählen, die auf der Seite hervorgehoben werden. Diese hervorgehobenen Listen werden allen Besuchern der Seite angezeigt.`,
  iO = `Es kann kein Kurator ausgewählt werden, da die Aktion sichtbar sein und begonnen haben muss.`,
  aO = `Tabs`,
  oO = `Über diese Schaltflächen können Sie anpassen, wie die unten angezeigten Inhalte auf der Seite erscheinen.`,
  sO = `Tab-Schaltflächen`,
  cO = `Optionaler Bereich. Verwenden Sie diesen Bereich nur, wenn bereits ein Tab vorhanden ist. Wir empfehlen, diesen Bereich unten auf der Seite zu platzieren, da Benutzer, die die Tabs auf der Seite ggf. übersehen, die Tabs dieses Bereichs als Schaltfläche für die einfache Navigation nutzen können.`,
  lO = `Auswahlfragen`,
  uO = `Dieser Bereich ermöglicht Ihnen, Ihren Kunden einige Quiz-artige Fragen mit Mehrfachantworten zur Auswahl zu stellen.`,
  dO = `Smart-Bereich des Punkteshops`,
  fO = `Dieser Bereich erfordert zur korrekten Funktion einen Kategorien-Tag. Das Kategorien-Tag wird dazu verwendet, die entsprechend markierten Punkteshop-Gegenstände automatisch zur Anzeige in diesem Bereich abzurufen.`,
  pO = `Communitygegenstandstyp`,
  mO = `Schränkt alle angezeigten Punkteshop-Gegenstände auf solche aus dieser Klasse ein. Diese Auswahl ist erforderlich. Hinweis: Der Profilmodifikator ist auch als „Spielprofile“ bekannt.`,
  hO = `Kategorien-Tag des Punkteshops`,
  gO = `Gibt an, welcher String der Kategorien-Tags für die Punkteshop-Gegenstände abgerufen werden soll. Bei diesem Tag handelt es sich wahrscheinlich um die Anmeldebezeichnung, z.\xA0B. „sale_halloween_2022“.`,
