  OO = `Empfohlen und bald verfügbar`,
  kO = `Noch nicht veröffentlichte Spiele, Zusatzinhalte, Software und Videos mit den für Nutzer empfohlenen Tags. (Grob) sortiert nach einer Mischung aus Veröffentlichungsdatum und Wunschlistenrang.`,
  AO = `Empfohlen und kostenlos`,
