  yk = `Sichtbarkeitseinstellungen für die Hardwarenutzung bearbeiten?`,
  bk = `Dieser Tab wird nur angezeigt, wenn der Nutzer eines dieser Hardwaregeräte verwendet hat. Wenn ein Gerät in diesem Bereich ausgewählt ist, wird dieser Bereich abgemeldeten Nutzern nicht angezeigt.`,
  xk = `Liste der zugelassenen verwendeten Geräte`,
  Sk = `Aktuelle Tabs`,
  Ck = `Jeder Tab definiert eine benannte Sammlung von Einträgen, die die folgenden Abschnitte zur Anzeige dieser Einträge filtern.`,
  wk = `Tabs sind eine Art Filter, mit dem Sie steuern können, welche Bereiche angezeigt werden. Definieren Sie Ihre Tabs hier und wählen Sie anschließend, welche Bereiche in den jeweiligen Tabs angezeigt werden sollen. Standardmäßig sind alle Bereiche in Tabs sichtbar.`,
  Tk = `Wählen Sie einen Tab aus, um ausschließlich die Bereiche im Editor anzuzeigen, die in diesem Tab sichtbar sind. Diese Funktion ist nur während der Bearbeitung im Editor verfügbar.`,
