  zk = `%1$s – Alle Gegenstände anzeigen`,
  Bk = `Dieser Tab ist so eingerichtet, dass alle Gegenstände in den folgenden Bereichen angezeigt werden. Wenn Sie jedoch unten klicken, können Sie eine Liste von Gegenständen erstellen, die dann in den folgenden Bereichen angezeigt werden, wenn dieser Tab aktiv ist.`,
  Vk = `Gefilterte Gegenstände bearbeiten`,
  Hk = `Hintergrundbild für den Tab auswählen (optional)`,
  Uk = `Ermöglicht die Einstellung eines Hintergrundbildes pro Tab, das bei dessen Auswahl erscheint. Es erstreckt sich oben auf dem Bildschirm über die gesamte Leiste des Tabs.`,
  Wk = `Hinweis: Filter fügen automatisch das Dialogfenster „Steam-Deck-Kompatibilität anzeigen“ zu Kapseln hinzu, das beim Bewegen des Mauszeigers darüber angezeigt wird.`,
  Gk = `Hinweis: Filter fügen automatisch das Dialogfenster „Steam-Frame-Kompatibilität anzeigen“ zu Kapseln hinzu, das beim Bewegen des Mauszeigers darüber angezeigt wird.`,
  Kk = `Hinweis: Filter fügen automatisch das Dialogfenster „Steam-Machine-Kompatibilität anzeigen“ zu Kapseln hinzu, das beim Bewegen des Mauszeigers darüber angezeigt wird.`,
