  Xk = `Sprungliste`,
  Zk = `Sprunglisten erscheinen unterhalb von Tabs und bieten einen schnellen Zugriff auf Bereiche, die unterhalb des Tabs angeführt werden. Dies ist vor allem dann nützlich, wenn Tabs in mehrere Bereiche unterteilt sind. `,
