  qM = `Im Bereich „Titel/Kopfzeile“ kann entweder Text oder ein Bild für die Beschreibung des nachfolgenden Inhalts angezeigt werden. Dieser kann außerdem mit dem Bereich „Tabs“ kombiniert werden, um automatisch zwei oder mehr Tabs als Untermenü anzuzeigen. Für die Tab-Funktionalität müssen Sie unten einen Kurznamen angeben.`,
