  sN = `Gefilterte Einträge löschen`,
  cN = `Hierdurch werden sämtliche mit Aktions-Tags versehenen und herausgefilterten Einträge gelöscht. Dies kann das Ausmaß der Aktion verringern und die Arbeit mit der Aktionsseite effizienter und einfacher gestalten.`,
