  MN = `Es werden nur Spiele angezeigt, die sich SOWOHL auf dieser Seite ALS AUCH unter den Top-150-Empfehlungen des aufrufenden Nutzers befinden. Nur veröffentlichte Anwendungen können empfohlen werden.`,
  NN = `Personalisiert: Spiele mit dem beliebtesten Tag`,
