  QV = `(Optional) Bild-URL des schemenhaften Abzeichens`,
  $V = `Optionale Elemente werden dem Nutzer, falls festgelegt, VOR dem Verdienst des tatsächlichen Abzeichens angezeigt. Dies ist insbesondere dann nützlich, wenn Sie die spezifischen Informationen zum Abzeichen verstecken möchten, bevor dieses verdient wurde. Das Element sollte 160\xA0×\xA0160 Pixel groß sein.`,
