  $W = `Bildbereiche erleichtern die Lokalisierung von Bildern und werden auf der den Kunden angezeigten endgültigen Aktionsseite schneller gerendert. Durch die Verwendung von Bildern im Titelbereich können Sie Unübersichtlichkeit im Bildauswahl-Werkzeug vermeiden.`,
