  DG = `Raw bearbeiten`,
  OG = `Ermöglicht für diese Aktion die direkte Bearbeitung der mit Aktions-Tags versehenen Artikel. Dies kann verwendet werden, um aus Werkzeugen wie Excel zu importieren oder exportieren bzw. schnell umfangreiche Änderungen an der Liste von Artikeln vorzunehmen.`,
  kG = `Benutzerdefinierte Aktions-Tags`,
  AG = `Erlaubt die direkte Bearbeitung der mit Aktions-Tags versehenen Artikel für diese Rabattaktion und den Import bzw. Export der benutzerdefinierten Tags für die Artikel. Dies dient primär dem Import von bestimmten über eine externe Tabelle verwalteten benutzerdefinierten Aktions-Tags, ohne andere Aktions-Tags dieser Artikel zu modifizieren. Darüber hinaus kann über dieses Dialogfenster ein Teil der Aktions-Tags importiert werden, da nicht aufgeführte Artikel hierdurch nicht entfernt werden.`,
  jG = `Von der Anmeldungsseite importieren`,
