  WG = `Dies ermöglicht die Einrichtung eines Filters, der auf alle mit Aktions-Tags versehenen Artikel vor Festlegung der Bereiche angewendet wird. Sie können diesen verwenden, um beispielsweise alle Spiele herauszufiltern, die über keine Demos verfügen oder einen zuvor bestimmten Aktions-Tag vorweisen.`,
  GG = `Durchsuchen`,
  KG = `Ermöglicht dem Filterwerkzeug, die aktuell konfigurierten und mit Aktions-Tags versehenen Artikel zu durchsuchen, um festzustellen, wie viele Artikel mit den verschiedenen Filtern übereinstimmen bzw. über damit verbundene Aktions-Tags verfügen.`,
  qG = `Als Gruppe bearbeiten`,
  JG = `Ermöglicht die Bearbeitung der mit Aktions-Tags versehenen Inhalte als Gruppe. Es kann eine Liste aller Inhalte angegeben werden, um Tags zu dieser Gruppe hinzuzufügen oder aus dieser zu entfernen.`,
