  ZK = `Hinweis: „Auf meiner Produktseite im Steam-Shop anzeigen“ ist in den Optionen abgewählt. Das Banner wird daher nicht im Steam-Shop angezeigt.`,
  QK = `Möchten Sie diesen Bereich wirklich von der Aktionsseite entfernen?`,
  $K = `Die Eventbeschreibung erscheint bereits in einem anderen Bereich. Möchten Sie sie wirklich auch hier anzeigen lassen?`,
