  cq = `Gegenstände nur an Tag %1$s (%2$s)`,
  lq = `Sichtbarkeit für neue Artikel`,
  uq = `Legt fest, an welchem Tag der Aktion die angegebenen Artikel angezeigt werden. Standardmäßig werden sie für alle Tage angezeigt. Mithilfe dieser Funktion können Angebote auf bestimmte Tage beschränkt werden.`,
  dq = `Aktionshintergründe pro Tag`,
  fq = `Standardmäßig wird ein einzelner Headerhintergrund für die gesamte Rabattaktion verwendet. Eine höhere Einstellung ermöglicht die Anzeige von unterschiedlichen Artworks für die verschiedenen Wochentage. Das Artwork des letzten Tages bleibt als standardmäßige Anzeige nach Ende der Aktion bestehen. Die Anzahl an verfügbaren Hintergründen basiert auf der Anzahl an Tagen, für die das Event im Optionstab definiert ist.`,
  pq = `%1$s Aktionsheader`,
  mq = `Einzelnes Aktionsheader-Artwork für das gesamte Event`,
  hq = `Wenn Sie diese Einstellung ändern, werden sämtliche zuvor ausgewählte Aktionsheader-Artworks von diesem Event entfernt. Fortfahren?`,
  gq = `Welches tagesspezifische Artwork (z. B. Dienstag) möchten Sie anzeigen/aktualisieren?`,
  _q = `Die Vorschau zeigt das für den ausgewählten Tag hochgeladene Artwork an. Jegliches mit dem Header verknüpfte Artwork wird ebenfalls auf den aktuell ausgewählten Tag angewendet.`,
  vq = `Sichtbar nur an Tag %1$s (von %2$s bis %3$s)`,
  yq = `Sichtbar nur an Tag %1$s sowie ab Tag %2$s`,
  bq = `oder`,
