  Oq = `Nicht gefunden`,
  kq = `Es können keine Informationen für (%1$s %2$s) gefunden werden. Es kann sich hierbei um einen Tippfehler handeln. Der Inhalt könnte auch versteckt oder nicht für Ihre Region sichtbar sein.`,
  Aq = `Nicht zulässig`,
  jq = `Dieser Inhalt kann nicht hinzugefügt werden, da er nicht mit dieser Erstellerseite (Entwickler, Publisher oder Franchise) verknüpft ist. Verknüpfen Sie den Inhalt und laden Sie die Aktionsseite erneut, um die Verknüpfung zu aktualisieren.`,
  Mq = `Bündel nicht zulässig`,
  Nq = `Dieses Bündel kann nicht hinzugefügt werden, da es nicht mit der Erstellerseite (Entwickler, Publisher oder Franchise) verknüpft ist. Verknüpfen Sie den Inhalt und laden Sie die Aktionsseite erneut, um die Verknüpfung zu aktualisieren. Folgende Anwendungen sind nicht mit der Erstellerseite verknüpft: (%1$s).`,
  Pq = `Paket nicht zulässig`,
  Fq = `Dieses Paket kann nicht hinzugefügt werden, da es nicht mit der Erstellerseite (Entwickler, Publisher oder Franchise) verknüpft ist. Verknüpfen Sie den Inhalt und laden Sie die Aktionsseite erneut, um die Verknüpfung zu aktualisieren. Folgende Anwendungen sind nicht mit der Erstellerseite verknüpft: (%1$s).`,
  Iq = `Das Event wurde aus einem vergangenen Event geklont. Um diese Aktionsseite konfigurieren zu können, muss diese von Valve aktiviert werden.`,
  Lq = `Seite für übergreifende Werbeaktionen`,
  Rq = `GID der Rabattaktion eingeben`,
  zq = `Hierbei handelt es sich um eine einzigartige ID am Ende der URL des Partner-Event-Editors. Es sollte nur die GID für die Aktionsseite verwendet werden. Weitere Informationen zu diesem Schritt finden Sie in der Dokumentation.`,
  Bq = `https://steamcommunity.com/groups/<groupname>/partnerevents/edit/<Ihre GID>`,
  Vq = `Eingegebene GID ist ungültig. GID muss ein numerischer Wert sein.`,
  Hq = `Aktionsseite verlinkt.`,
  Uq = `Das Event existiert, jedoch kann derzeit kein Link dafür erstellt werden. Entweder sind die Werkzeuge für Aktionen deaktiviert oder dem Event wurden bislang keine Spiele hinzugefügt, weshalb die interne ID für die Verlinkung fehlt. Bitten Sie den Organisator, die Aktionsseite vollständig einzurichten und versuchen Sie es erneut.`,
  Wq = `Informationen zur Aktionsseite werden geladen …`,
  Gq = `Aktionsseite ist weder veröffentlicht noch sichtbar.`,
  Kq = `Titel der Aktionsseite: %1$s`,
  qq = `Diese Shopseite enthält keine Event-Kapselbilder`,
  Jq = `Anwendungsauswahl`,
  Yq = `Wunschlisteneinträge priorisieren`,
  Xq = `Wenn die Seite für übergreifende Werbeaktionen hauptsächlich bald verfügbare Titel enthält, sind für diese wahrscheinlich keine Daten zu den Einnahmen verfügbar. In diesem Fall wird die Priorisierung nach Wunschlisteneinträgen bevorzugt.`,
  Zq = `Einnahmen priorisieren`,
  Qq = `Diese Standardeinstellung nutzt Informationen zu aktuellen Topsellern, um Spiele zu priorisieren, die Kunden auf der Seite für übergreifende Werbeaktionen angezeigt werden.`,
  $q = `Bei mehr als einer Aktionsseite wird der Bereich als Karussell angezeigt, das jede Aktionsseite in dieser Reihenfolge einzeln hervorhebt. Die Reihenfolge kann durch Ziehen der Karussellseiten verändert werden.`,
  eJ = `Weitere Aktionsseite hinzufügen`,
