  lJ = `Geben Sie keine Beschreibung ein, um diese Option als einzelne Zeile anzuzeigen: Paketname, Preis und „Kauf“-Schaltfläche, ohne Bild oder geschätzte Lieferzeit.`,
  uJ = `Layout`,
  dJ = `In der Rasteransicht werden Blöcke mit fester Breite in Zeilen angeordnet. In der Listenansicht wird hingegen ein Block pro Zeile mit Bild neben dem Text angezeigt.`,
  fJ = `Raster`,
