  hJ = `Nicht vorrätige Pakete werden bei Aktivierung dieser Option aus diesem Bereich entfernt, anstatt mit dem Hinweis „Nicht vorrätig“ gekennzeichnet zu werden. (Standardmäßig deaktiviert)`,
  gJ = `Farben für kompakte Zeilen`,
  _J = `Diese werden auf Optionen angewandt, die als einzelne Zeile angezeigt werden, also ohne Beschreibung. Alle weiteren Optionen, für die die Standardeinstellung festgelegt wurde, werden standardmäßig angezeigt.`,
