  VJ = `Bei der automatischen Generierung von Facetten werden alle bestehenden Facetten überschrieben. Fortfahren?`,
  HJ = `Verwenden Sie für Anwendungen mit dem Shop-Tag „Controller“ das Aktions-Tag für angesagte Artikel.`,
  UJ = `Nicht verwendete Facetten entfernen`,
  WJ = `Entfernen`,
  GJ = `Mindestanzahl passender Kapselbilder für Facettenwerte`,
  KJ = `Vorgeschlagener Wert: 5`,
  qJ = `Maximaler Facettenwert pro Facette`,
  JJ = `Vorgeschlagener Wert: 5`,
  YJ = `Facettenwerte sortieren`,
  XJ = `Nach Namen`,
  ZJ = `Nach Anzahl der Übereinstimmungen`,
  QJ = `Manuell`,
  $J = `Name dieses Facettenwerts. Ein Facettenwert ist eine benutzerdefinierte Option, auf die Nutzer klicken können, um die angezeigten Spiele in diesem Abschnitt zu filtern. Beispiel: „Egoshooter“.`,
  eY = `Optionaler Text, der auf der rechten Seite des Facettenwerts angezeigt wird. Verwenden Sie diesen, um einen Facettenwert sehr kurz zu beschreiben. Beispiel: „1–2 Stunden“ für einen Facettenwert, der auf Spiele mit sehr kurzer Spielzeit zutrifft.`,
  tY = `Name dieser Facette. Eine Facette ist eine Gruppe verwandter Optionen. Nutzer können auf jede einzelne davon klicken, um die in diesem Bereich angezeigten Spiele zu filtern. Beispiel: „Genre“.`,
  nY = `Diese Option füllt die Facetten und Facettenwerte automatisch auf Basis von Shop-Tag-Kategorien wie „Genre“ und „Visueller Stil & Perspektive“ auf. Nach der automatischen Erstellung können Sie bei Bedarf manuell auf jede einzelne Facette und jeden einzelnen Facettenwert klicken.`,
  rY = `Diese Option entfernt alle Facettenwerte, die nicht mit mindestens einem der Artikel in diesem Bereich übereinstimmen.`,
  iY = `Was ist die Mindestanzahl für Ergebnisse, die Sie für eine ausgewählte Facette erhalten möchten? Diese Option verbirgt jegliche Begriffe im linken Menü, die diese Mindestanzahl an Übereinstimmungen nicht enthalten. Diese Anzahl wird nach Anwendung von aktiven Tab-Filtern kalkuliert. Wir empfehlen üblicherweise eine Zahl in einem Intervall um 5.`,
  aY = `Diese Option zeigt höchstens diese Anzahl an Optionen in den Hauptkategorien des linken Menüs an. Beispiel: Zeige nicht mehr als diese Anzahl an Genres in der Facette namens „Genre“ an. Wir empfehlen üblicherweise eine Zahl in einem Intervall um 5.`,
  oY = `Die Facettenwerte werden für jede Facette nach dieser Metrik sortiert. Wir empfehlen üblicherweise eine Sortierung nach Anzahl der Übereinstimmungen.`,
  sY = `Innerhalb jeder Facette werden die Facettenwerte in alphabetischer Reihenfolge ihres Namens sortiert.`,
  cY = `Innerhalb jeder Facette werden Facettenwerte absteigend nach der Anzahl von mit ihnen übereinstimmenden Artikeln sortiert. Beispiel: Unter der Facette „Genre“ erscheint „Rollenspiel“ vor „Strategie“, wenn es in diesem Bereich mehr Rollenspiele als Strategiespiele gibt.`,
  lY = `Facettenwerte nicht sortieren. Diese werden in der festgelegten Reihenfolge in den Listen unten angezeigt.`,
  uY = `Hervorgehobene Facettenfarbe`,
  dY = `Farbe der Überschrift`,
