  pY = `Die 20 beliebtesten Shop-Tags synchronisieren`,
  mY = `Standardmäßig werden nur die 10 beliebtesten Shop-Tags pro Artikel synchronisiert. Markieren Sie dieses Kästchen, um stattdessen die 20 beliebtesten Shop-Tags zu synchronisieren.`,
  hY = `Informationen zum Debuggen generieren`,
  gY = `Logisch UND`,
  _Y = `Wenn diese Option aktiviert ist und der Benutzer mehrere Facettenwerte in dieser Facette auswählt, werden der logische UND der ausgewählte Facettenwertfilter angewendet. Andernfalls wird der logische ODER der ausgewählte Facettenwertfilter angewendet.`,
  vY = `Zunächst erweitert`,
