  SY = `Einstellungen für die Artikelquelle (Optional)`,
  CY = `Statt einer Liste verknüpfter Anwendungen können Sie den Namen eines Inhaltshubs angeben, aus dem für diese Aktion Artikel herausgezogen werden. Falls angegeben, wird die verknüpfte Anwendungsliste für diese Aktion ignoriert und die Aktionsseite zeigt alles aus dem jeweiligen Inhaltshub an.`,
  wY = `Inhaltshubtyp`,
