  LY = `Max. erlaubte Anzahl`,
  RY = `Wie viele virtuellen Gegenstände dieses Typs auf einmal gekauft werden dürfen. Um die Auswahlliste für die Anzahl zu deaktivieren, setzen Sie diese Option auf 0 oder 1.`,
