  BY = `Virtuellen Gegenstand hinzufügen`,
  VY = `Sie können das mit dem virtuellen Gegenstand verknüpfte Standard-Artwork durch Upload eines neuen Artworks überschreiben. Andernfalls verwenden wir das Bild, das sonst im Gegenstandsshop für den Gegenstand angezeigt werden würde.`,
  HY = `Holen Sie sich Ihren kostenlosen Gegenstand`,
  UY = `Ein Bereich, in dem Nutzer einen kostenlosen Gegenstand erhalten. Er gibt den Zeitraum für den nächstmöglichen Erhalt an (falls zutreffend). Dies kann für die tägliche Veröffentlichung von Gegenständen genutzt werden. Der Bereich ist mit dem Widget für Belohnungen verbunden, um die Steuerung für den Erhalt von Aktionsgegenständen zu steuern.`,
  WY = `Optional: Schaltfläche „Einlösen“ umbenennen`,
