  KY = `Persönlicher Kalender`,
  qY = `Ein Bereich für bald verfügbare Titel, die Ihnen empfohlen werden oder die sich auf Ihrer Wunschliste befinden. Titel werden für eine bestimmte Anzahl von Tagen angezeigt.`,
