  MX = `Beliebt`,
  NX = `Lassen Sie sich übergeordnete Anwendungen zuerst anzeigen, die die beliebtesten Zusatzinhalte haben. Die Beliebtheit wird durch den Verkaufsrang bestimmt. Zusatzinhalte mit niedrigen Verkaufszahlen werden ggf. nicht berücksichtigt.`,
  PX = `Maximal zurückliegende Spielzeit (Monate)`,
