  RX = `Anzuzeigende übergeordnete Anwendungen`,
  zX = `Zeigt beim Laden der Seite nur Zusatzinhalte bis zur angegebenen Anzahl Spiele an. Wenn weitere Zusatzinhalte vorhanden sind, können Nutzer diese über die Schaltfläche „Mehr anzeigen“ einsehen.`,
