  sZ = `Seite wurde nicht gefunden.`,
  cZ = `Zum Dashboard`,
  lZ = `Wählen Sie eine oder mehrere Datei(en) zum Hochladen aus, um einen lokalisierten Text für Ihren Titel und Beschreibung zu importieren. Die Dateierweiterung bestimmt die zu importierende Dateiart (XML- oder CSV-Datei). Bei XML-Dateien wird die Sprache des Inhalts anhand des API-Sprachcodes am Ende des Dateinamens vor der Dateiendung erkannt. Beginnen Sie mit dem Export einer der CSV- oder XML-Datei, um sicherzustellen, dass Sie mit dem richtigen Format arbeiten.`,
  uZ = `Exportiert die aktuelle Sprache in eine Einzeldatei des ausgewählten Typs. XML erstellt stets eine Einzeldatei mit der aktuellen Editorsprache. CSV exportiert alle verfügbaren Sprachen in eine Einzeldatei.`,
  dZ = `Bilder`,
  fZ = `Häufig gestellte Fragen bearbeiten`,
  pZ = `Häufig gestellte Fragen löschen\xA0…`,
  mZ = `Diesen Eintrag für häufig gestellte Fragen dauerhaft löschen.`,
  hZ = `Die Löschung des Eintrags für häufig gestellte Fragen wird sofort übernommen und kann nicht wieder rückgängig gemacht werden. Möchten Sie diesen Artikel und alle damit verbundenen lokalisierten Inhalte wirklich löschen?`,
  gZ = `Eintrag wird gelöscht. Bitte warten\xA0…`,
  _Z = `Die Löschung wurde abgeschlossen. Sie können nun das Dialogfeld schließen, um zum Dashboard zurückzukehren.`,
  vZ = `Sichtbarkeit ändern`,
  yZ = `Bearbeiten`,
  bZ = `Über diese Optionen können Sie die häufig gestellten Fragen auf der gewünschten Plattform sichtbar machen. Die Änderung auf den Status „sichtbar“ erfordert eine veröffentlichte Version in der entsprechenden Sprache oder einer anderen, in der Region zugelassenen, Sprache.`,
  xZ = `Die Regionssichtbarkeit der häufig gestellten Fragen kann über dieses Dialogfeld geändert werden. Sollte das Dokument nicht sichtbar sein, ist es selbst nach Veröffentlichung nicht zugänglich.`,
  SZ = `Die Sichtbarkeitseinstellungen dieser häufig gestellten Fragen werden aktualisiert.`,
  CZ = `Die Sichtbarkeitseinstellungen wurden erfolgreich aktualisiert.`,
  wZ = `Auf Steam Global sichtbar`,
  TZ = `Auf Steam China sichtbar`,
  EZ = `Hinweis: Inhalte für Steam China müssen in vereinfachtem Chinesisch oder vereinfachtem Chinesisch (Steam China) lokalisiert und veröffentlicht werden, um auf Steam China angezeigt zu werden.`,
  DZ = `Veröffentlichte häufig gestellte Fragen anzeigen`,
  OZ = `Internen Namen der häufig gestellten Fragen ändern`,
  kZ = `Die Änderung des internen Namens der häufig gestellten Fragen (nur für Bearbeiter sichtbar) wird nach der Genehmigung sofort angewendet.`,
  AZ = `Veröffentlichen`,
  jZ = `Veröffentlichen Sie Entwürfe in ein oder mehreren Sprachen als öffentliche Version. Hinweis: Die Sichtbarkeit wird separat über die veröffentlichten Versionen kontrolliert.`,
  MZ = `Speichern Sie, um mit dem Veröffentlichungsprozess beginnen zu können.`,
  NZ = `Häufig gestellten Fragen werden veröffentlicht. Bitte warten\xA0…`,
  PZ = `Veröffentlichung erfolgreich abgeschlossen.`,
  FZ = `Sobald Sie einen Entwurf veröffentlichen, wird dieser zur Live-Version. Die folgenden Sprachen haben Änderungen im Entwurf. Wählen Sie die gewünschte Version aus, um diese jetzt zu veröffentlichen.`,
  IZ = `Hinweis: Die Veröffentlichung und der Sichtbarkeitsstatus sind voneinander getrennt. Der Sichtbarkeitsstatus für die Steam-Region (Steam Global oder Steam China) muss separat festgelegt werden.`,
  LZ = `Ladefehler: Zur Veröffentlichung des Dokuments fehlen die erforderlichen vorherigen Veröffentlichungsinformationen. Bitte Seite neu laden.`,
  RZ = `Aktueller Veröffentlichungsstatus wird geladen`,
